function d_pipeline(P,R){var layers=['intelligence','knowledge','creation','experiment','verification','evolution'];var plan=layers.map(function(l,i){return{layer:l,artifacts:1+Math.floor(R()*3),est_hours:Math.round(4+R()*40)};});return{objective:P.objective,ecosystem:plan,total_artifacts:plan.reduce(function(s,p){return s+p.artifacts;},0)};}

// invoked with params:
// {"objective":"create a self-healing structural material for bridges"}

function d_agents(P,R){var specs=P.specialists||['materials','mechanisms','cost','safety'];var scores=specs.map(function(s){var v=0.5+0.5*R();return{specialist:s,score:+v.toFixed(3),verdict:v>0.6?'approve':'revise'};});return{proposal:P.proposal,reviews:scores,approved:scores.every(function(s){return s.verdict==='approve';})};}

// invoked with params:
// {"proposal":"Adaptive Structure Generator","specialists":["CALPHAD phase diagrams","crystal structures","metamaterial lattices","fatigue laws"]}

function d_kbquery(P,R){var docs=P.docs||[];var q=(P.query||'').toLowerCase().split(/\s+/);var sc=docs.map(function(d){var t=(d.title+' '+d.text).toLowerCase();var hit=q.filter(function(w){return w&&t.indexOf(w)>=0;}).length;return{id:d.id,title:d.title,score:+(hit/Math.max(1,q.length)).toFixed(2)};});sc.sort(function(a,b){return b.score-a.score;});return{query:P.query,matches:sc.filter(function(s){return s.score>0;}).length,top:sc.slice(0,3)};}

