function d_verify(P,R){var checks=P.checks||[];var rows=checks.map(function(c){var pass=R()<(c.difficulty?1.1-c.difficulty:0.85);return{check:c.name,pass:pass};});var passed=rows.filter(function(r){return r.pass;}).length;return{checks:rows,passed:passed,total:rows.length,verdict:passed===rows.length?'VERIFIED':'NEEDS WORK'};}

