function d_audit(P,R){var claims=P.claims||[];var rows=claims.map(function(c){var st=c.evidence==='demonstrated'?'has-demonstrated':c.evidence==='simulated'?'can-generate':'knows';return{claim:c.text,status:st};});return{claims:rows,counts:{knows:rows.filter(function(r){return r.status==='knows';}).length,'can-generate':rows.filter(function(r){return r.status==='can-generate';}).length,'has-demonstrated':rows.filter(function(r){return r.status==='has-demonstrated';}).length}};}

